// Regenerates src/assets/svgs/index.ts from the .svg files exported from Figma.
// Usage: node scripts/generate-svgs.js
const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, '..', 'src', 'assets', 'svgs');
const files = fs
  .readdirSync(dir)
  .filter(file => file.endsWith('.svg'))
  .sort();

let out =
  '// AUTO-GENERATED by scripts/generate-svgs.js from the Figma exports in this folder.\n' +
  '// Do not edit by hand. Render with <CustomSvg name="..." />.\n\n' +
  'export const SVGS = {\n';

for (const file of files) {
  const xml = fs
    .readFileSync(path.join(dir, file), 'utf8')
    // Web-only CSS attribute that react-native-svg cannot apply.
    .replace(/\s*style="display: block;"/g, '')
    .trim();
  out += `  ${path.basename(file, '.svg')}: ${JSON.stringify(xml)},\n`;
}

out += '};\n\nexport type SvgName = keyof typeof SVGS;\n';
fs.writeFileSync(path.join(dir, 'index.ts'), out);
console.log(`Generated ${files.length} SVGs`);
